// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        vm.assume(target != address(c));
        vm.assume(value <= address(c).balance);
        uint256 depositsBefore = c.depositsCount();
        (bool success, ) = address(c).call{value: 0}(data);
        vm.prank(c.owner());
        (bool sentOk, ) = address(c).call(abi.encodeWithSelector(c.sendMoney.selector, target, value, data));
        vm.assume(success && sentOk);
        uint256 depositsAfter = c.depositsCount();
        assertTrue(depositsAfter == depositsBefore + 1);
    }
}

